public class Main {

    public static int maxLength(int[] arr, int k) {
        int n = arr.length;

        int left = 0;
        int sum = 0;
        int ans = 0;

        for (int right = 0; right < n; right++) {
            sum += arr[right];

            while (sum > 2 * k) {
                sum -= arr[left];
                left++;
            }

            // Need two non-empty partitions.
            // Find a valid split inside the current window.
            if (right - left + 1 >= 2) {
                int prefix = 0;

                for (int i = left; i < right; i++) {
                    prefix += arr[i];

                    int suffix = sum - prefix;

                    if (prefix <= k && suffix <= k) {
                        ans = Math.max(ans, right - left + 1);
                        break;
                    }
                }
            }
        }

        return ans;
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 1, 1, 2};
        int k = 4;

        System.out.println(maxLength(arr, k));
    }
}
